mapper.select:


    a.deleted = 0
     and a.name like concat('%', #{name}, '%')
     and a.customer_id = #{customerId}


        and exists (select 1 from crm_business_product bp
                     where bp.bus_id = a.id and bp.supplier_id = #{supplierId})

     and a.owner_user like concat('%', #{ownerUser}, '%')
     and a.bus_status = #{busStatus}


        and find_in_set(a.bus_status, #{params.statusList})

     and a.contact_status = #{contactStatus}


        and a.deal_time >= #{params.beginDealTime}


        and a.deal_time <= concat(#{params.endDealTime}, ' 23:59:59')



        and a.create_time >= #{params.beginTime}


        and a.create_time <= concat(#{params.endTime}, ' 23:59:59')



        and a.customer_id in

            #{scopeCustomerId}




        and a.creator = #{params.scopeCreator}


order by a.id desc
